CREATE OR REPLACE VIEW public.purchase_reconciliation_summary AS SELECT r.*,po.po_number,po.supplier_id,s.name AS supplier_name,si.invoice_number,pr.receipt_number FROM public.purchase_reconciliations r JOIN public.purchase_orders po ON po.id=r.purchase_order_id JOIN public.suppliers s ON s.id=po.supplier_id LEFT JOIN public.supplier_invoices si ON si.id=r.supplier_invoice_id LEFT JOIN public.purchase_receipts pr ON pr.id=r.purchase_receipt_id;